def apply(inputs, premises):
    is_dependent = inputs["individual_is_qualifying_child_of_another_taxpayer"] and premises["qualifying_child_is_dependent"]
    applies = is_dependent and premises["dependent_has_no_dependents"]
    entailed = applies == inputs["claim_affirms_application"]
    if entailed:
        answer = "Entailment"
    else:
        answer = "Contradiction"
    return {"answer": answer}
